import { expect, test } from "bun:test";
import {
	appendConversationPolicy,
	conversationTools,
	operation,
} from "../service/conversation-tools";

// These are host contract tests: tool calls are supplied, not generated by an LLM.
test("the host preserves the selected researcher and question without topic-based rerouting", () => {
	const tools = conversationTools(false, true);
	for (const question of ["今日のニュース。", "仙台は何県？"])
		for (const name of ["research", "research_web_luna"]) {
			const args =
				name === "research" ? { kind: "web", question } : { question };
			expect(
				operation(
					[{ id: "call", name, arguments: JSON.stringify(args) }],
					tools,
				),
			).toEqual({
				kind: "web",
				question,
				...(name === "research_web_luna" ? { researcher: "codex_luna" } : {}),
			});
		}
});

test("Luna is not callable when unavailable and cannot request history or coding scope", () => {
	const call = {
		id: "call",
		name: "research_web_luna",
		arguments: '{"question":"説明して"}',
	};
	expect(() => operation([call], conversationTools(false))).toThrow(
		"invalid_conversation_operation",
	);
	for (const kind of ["history", "coding"])
		expect(() =>
			operation(
				[
					{
						...call,
						arguments: JSON.stringify({ question: "説明して", kind }),
					},
				],
				conversationTools(false, true),
			),
		).toThrow();
	expect(() =>
		operation(
			[
				{
					...call,
					name: "research",
					arguments:
						'{"kind":"history","question":"以前の話","researcher":"codex_luna"}',
				},
			],
			conversationTools(false, true),
		),
	).toThrow();
});

test("the search replacement accepts a query without asking for requirement profiles", () => {
	const tools = conversationTools(false, true);
	expect(
		operation(
			[
				{
					id: "call",
					name: "research_web_luna",
					arguments: JSON.stringify({ question: "公開情報を検索" }),
				},
			],
			tools,
		),
	).toEqual({
		kind: "web",
		researcher: "codex_luna",
		question: "公開情報を検索",
	});
	expect(() =>
		operation(
			[
				{
					id: "call",
					name: "research_web_luna",
					arguments: JSON.stringify({
						question: "公開情報を検索",
						requirementProfiles: ["p1"],
					}),
				},
			],
			tools,
		),
	).toThrow();
});

test("requirement profiles reach history only; a web search never carries a requirement contract", () => {
	const tools = conversationTools(false, true);
	const call = (args: unknown) =>
		operation(
			[{ id: "call", name: "research", arguments: JSON.stringify(args) }],
			tools,
		);
	expect(() =>
		call({
			kind: "web",
			question: "仙台は何県？",
			requirementProfiles: ["p1"],
		}),
	).toThrow();
	const schema = tools.find((t) => t.function.name === "research")!.function
		.parameters as any;
	expect(schema.oneOf[0].properties.requirementProfiles).toBeUndefined();
	expect(schema.oneOf[0].additionalProperties).toBe(false);
	expect(schema.oneOf[1].properties.requirementProfiles).toBeDefined();
	expect(
		call({
			kind: "history",
			question: "以前の話",
			requirementProfiles: ["p1"],
		}),
	).toEqual({
		kind: "history",
		question: "以前の話",
		requirementProfiles: ["p1"],
	});
});

test("the conversation policy and tool descriptions name Luna only when Luna is exposed", () => {
	for (const luna of [false, true]) {
		const messages = [
			{ role: "system" as const, content: "人格" },
			{ role: "user" as const, content: "今朝のニュースを教えて" },
		];
		appendConversationPolicy(messages, null, luna);
		const tools = conversationTools(false, luna);
		const text = JSON.stringify([messages, tools]);
		expect(text.includes("research_web_luna")).toBe(luna);
		expect(messages.at(-1)!.content).toBe("今朝のニュースを教えて");
		expect(
			messages.some((m) => m.content.includes("そのまま自然文で返します")),
		).toBe(true);
	}
});

test("the conversation policy never asks for a profile argument that the web branch rejects", () => {
	for (const luna of [false, true]) {
		const messages = [
			{ role: "system" as const, content: "人格" },
			{ role: "user" as const, content: "マイクロソフトの株価" },
		];
		appendConversationPolicy(messages, null, luna);
		const policy = messages.at(-2)!.content;
		expect(policy).not.toContain("空配列");
		expect(policy).toContain("webの引数にはrequirementProfilesを含めません");
	}
	expect(() =>
		operation(
			[
				{
					id: "call",
					name: "research",
					arguments: JSON.stringify({
						kind: "web",
						question: "株価",
						requirementProfiles: ["p1"],
					}),
				},
			],
			conversationTools(false, false),
		),
	).toThrow();
});
